  propbeam: (r, S) => Pl([[-S * 0.9, S * 0.9], [-S * 0.7, S * 0.95], [S * 0.6, -S * 0.75], [S * 0.4, -S * 0.85]], WOOD, S) + Pl([[S * 0.35, -S], [S * 0.6, -S], [S * 0.6, S], [S * 0.35, S]], WOOD_D, S) + hatch([-S * 0.6, S * 0.6], [S * 0.3, -S * 0.5], 6, S * 0.1, S),
