  breathcloud: (r, S, c) => { const m = add(c.face, [S * 0.35, S * 0.1]); let s = ''; for (let i = 0; i < 4; i++) { const q = add(m, [S * (0.35 + i * 0.45), -S * i * 0.12]); s += K.billow(r, q, S * (0.25 + i * 0.12), S * (0.14 + i * 0.06), '#e8e4dc', { op: 0.8 - i * 0.12, lw: 2, curls: 1 }); } return s + K.drybrush(r, [m, add(m, [S * 0.5, -S * 0.05]), add(m, [S * 1.4, -S * 0.3])], S * 0.08, '#f0ece4', { dry: 0.9, op: 0.7, body: false, bristles: 5 }); },
  lightshaft: (r, S, c) => { const p = c.act, top = [p[0] - S * 0.6, 0], w0 = S * 0.9, w1 = S * 0.45; let s = `<path d="M${f1(top[0] - w0)},0L${f1(top[0] + w0)},0L${f1(p[0] + w1)},${f1(p[1])}L${f1(p[0] - w1)},${f1(p[1])}Z" fill="#f4e8b8" opacity="0.72"/><path d="M${f1(top[0] - w0 * 0.4)},0L${f1(top[0] + w0 * 0.4)},0L${f1(p[0] + w1 * 0.4)},${f1(p[1])}L${f1(p[0] - w1 * 0.4)},${f1(p[1])}Z" fill="#fffbe8" opacity="0.8"/>`; for (let i = 0; i < 5; i++) { const t = i / 4; s += L([[top[0] - w0 + t * 2 * w0, 0], [p[0] - w1 + t * 2 * w1, p[1]]], i % 4 ? 2.4 : 4, i % 4 ? GILT : INK, { op: 0.85 }); } for (let i = 0; i < 18; i++) { const t = r(), x = lerp([top[0], 0], [p[0], 0], t)[0] + (r() - 0.5) * lerp([w0, 0], [w1, 0], t)[0] * 1.6; s += `<circle cx="${f1(x)}" cy="${f1(t * p[1])}" r="${f1(1.6 + r() * 2)}" fill="#fff4d0"/>`; } return s; },
