  hail: (r, S, c) => { let s = ''; for (let i = 0; i < 30; i++) { const q = [r() * c.W, r() * (c.floor - 30)], z = 9 + r() * 10; s += L([add(q, [z * 1.2, -z * 4]), q], z * 0.5, PALE, { op: 0.55 }) + O(q, z, z, ICE, S, { w: 2.4 }) + `<circle cx="${f1(q[0] - z * 0.3)}" cy="${f1(q[1] - z * 0.3)}" r="${f1(z * 0.32)}" fill="#fff"/>`; } for (let i = 0; i < 10; i++) { const q = [r() * c.W, c.floor - 8 - r() * 6], z = 8 + r() * 6; s += O(q, z, z * 0.8, ICE, S, { w: 2 }); } return s; },
