  flies: (r, S, c) => { let s = ''; const ctr = lerp(c.head, c.hip, 0.4); for (let i = 0; i < 46; i++) { const a = r() * 6.28, d = S * (0.4 + r() * 2.2), q = add(ctr, [Math.cos(a) * d * 1.3, Math.sin(a) * d * 0.8]), z = 5 + r() * 3; s += O(q, z, z * 0.75, INK, S, { w: 1 }) + O(add(q, [-z * 0.6, -z * 0.9]), z * 0.8, z * 0.45, PALE, S, { w: 1, op: 0.85 }) + O(add(q, [z * 0.6, -z * 0.9]), z * 0.8, z * 0.45, PALE, S, { w: 1, op: 0.85 }); } return s; },
  stormcloud: (r, S, c) => { const x = c.hit[0] + S * 0.4, pts = [[x, S * 0.9]]; let p = pts[0]; while (p[1] < c.floor - 20) { p = add(p, [(r() - 0.5) * S * 0.8, S * (0.35 + r() * 0.25)]); pts.push([p[0], Math.min(p[1], c.floor)]); } let s = K.billow(r, [x, S * 0.25], S * 2.6, S * 0.7, '#3a3a44', { op: 0.95, lw: 4, curls: 3 }); s += L(pts, S * 0.16, INK) + L(pts, S * 0.07, '#efe2a8'); return s + `<ellipse cx="${f1(p[0])}" cy="${f1(c.floor)}" rx="${f1(S * 0.6)}" ry="${f1(S * 0.12)}" fill="#efe2a8" opacity="0.6"/>`; },
  bloodmoon: (r, S, c) => { const R = S * 1.5, band = side => { let n = 0; for (let y = 0; y < Math.round(c.GH * 0.45); y++) for (let x = 0; x < Math.round(c.GW * 0.35); x++) n += c.occ[y * c.GW + (side ? c.GW - 1 - x : x)]; return n; }, cx = band(1) <= band(0) ? c.W * 0.8 : c.W * 0.2, cy = R * 0.45;   /* the side of the sky the figure leaves open */ return O([cx, cy], R, R, '#b0402c', S, { w: 5 }) + O([cx + R * 0.3, cy + R * 0.25], R * 0.2, R * 0.16, '#7a2418', S, { w: 0 }) + O([cx - R * 0.35, cy - R * 0.05], R * 0.26, R * 0.2, '#7a2418', S, { w: 0 }) + L(K.arc([cx, cy], R * 0.92, R * 0.92, 100, 200, 10), R * 0.05, '#e8a080', { op: 0.8 }) + hatch([cx - R * 0.6, cy + R * 0.5], [cx + R * 0.6, cy + R * 0.5], 9, R * 0.25, S, 1.9); },   /* a moon in the sky, cut by the frame top (the room's own top) */
  star: (r, S, c) => { const x0 = c.hit[0] + S * 1.2, p = [x0, S * 0.3], q = [x0 - S * 0.8, c.floor - S * 0.2]; return K.drybrush(r, [p, lerp(p, q, 0.5), q], S * 0.22, '#e8eef4', { profile: t => 0.1 + 0.9 * t, dry: 0.7, op: 0.85, body: false, bristles: 8 }) + Pl([add(q, [0, -S * 0.55]), add(q, [S * 0.14, -S * 0.14]), add(q, [S * 0.55, 0]), add(q, [S * 0.14, S * 0.14]), add(q, [0, S * 0.55]), add(q, [-S * 0.14, S * 0.14]), add(q, [-S * 0.55, 0]), add(q, [-S * 0.14, -S * 0.14])], '#e8eef4', S) + `<ellipse cx="${f1(q[0])}" cy="${f1(c.floor)}" rx="${f1(S * 0.6)}" ry="${f1(S * 0.1)}" fill="#dce8ee" opacity="0.7"/>`; },
  meteors: (r, S, c) => { let s = ''; for (let i = 0; i < 5; i++) { const q = [c.W * (0.12 + i * 0.19) + (r() - 0.5) * 60, S * (0.6 + r() * 1.6)], z = S * (0.22 + r() * 0.14); s += L([add(q, [-S * 1.4, -S * 1.2]), q], S * 0.07, PALE, { op: 0.6 }) + Pl([add(q, [0, -z]), add(q, [z * 0.25, -z * 0.25]), add(q, [z, 0]), add(q, [z * 0.25, z * 0.25]), add(q, [0, z]), add(q, [-z * 0.25, z * 0.25]), add(q, [-z, 0]), add(q, [-z * 0.25, -z * 0.25])], '#e8eef4', S, { w: 2 }); } const g = [c.hit[0], c.floor - 6]; s += L([add(g, [-S * 1.6, -S * 2.2]), g], S * 0.08, PALE, { op: 0.65 }) + K.splatter(r, g, S * 0.8, '#e8eef4', { dir: [0, -1], spread: 1.8, n: 10, blotR: 0.12 }); return s; },
